SELECT 'core-2026-09-v4','stative-dynamic','87b630c771d79eac83e3be02f06e226cf9455e201ca4d4e9ebd574542396373d',payload || '{"slug":"stative-dynamic","title":"States and actions: simple or continuous?","level":"B1","order":30,"summary":"Choose a verb form from its meaning: a state, an activity or a temporary behaviour.","guidance":"Read the form and meaning together. Study the contrasts, then explain a worked example in your own words before starting a fresh practice session.","learningGoals":["States are not normally continuous","A verb can change meaning","Temporary behaviour with being","Perception and deliberate activity"],"rules":[{"title":"States are not normally continuous","explanation":"Know, believe, own and need commonly describe states rather than activities unfolding moment by moment. They usually take simple forms even when true now. A word such as now does not force every verb into the continuous.","pattern":"I **know** the answer now.","commonMistakes":["I am knowing the answer is not the ordinary standard form for possession of knowledge."],"examples":["Describe present knowledge: “I **know** how to prepare the visitor guide.”","Describe present knowledge: “I **know** how to restore the old portrait.”"],"skill":"form"},{"title":"A verb can change meaning","explanation":"Think can mean hold an opinion or actively consider. Have can mean possess or take part in an activity. Use the meaning in the sentence to decide whether continuous aspect is natural.","pattern":"I **think** it is useful. / I **am thinking about** the problem.","commonMistakes":["A memorised list of stative verbs is not enough: the same spelling can have a dynamic sense."],"examples":["Use present continuous for active consideration: “We **are thinking** about how to prepare the visitor guide.”","Use present continuous for active consideration: “We **are thinking** about how to restore the old portrait.”"],"skill":"meaning"},{"title":"Temporary behaviour with being","explanation":"Be usually describes a state, but **be being + adjective** can describe temporary behaviour. You are being helpful comments on someone’s behaviour now. It does not mean that every adjective works naturally in this pattern.","pattern":"He **is being patient** today.","commonMistakes":["He is being tall does not normally describe temporary behaviour; height is a characteristic."],"examples":["State an opinion, in the simple present: “She **thinks** that preparing the visitor guide is worthwhile.”","State an opinion, in the simple present: “She **thinks** that restoring the old portrait is worthwhile.”"],"skill":"contrast"},{"title":"Perception and deliberate activity","explanation":"See and hear often describe involuntary perception and use simple forms or can. Other senses can describe deliberate activity: tasting soup or smelling a flower. See can also mean meet, which permits a continuous arrangement.","pattern":"I **can hear** music. / She **is tasting** the soup.","commonMistakes":["Advertising and informal emphatic uses sometimes put state verbs in the continuous. Practice here follows the ordinary meaning stated in each prompt."],"examples":["Comment on temporary helpful behaviour: “You **are being** helpful by preparing the visitor guide for us today.”","Comment on temporary helpful behaviour: “You **are being** helpful by restoring the old portrait for us today.”"],"skill":"application"}],"tips":[],"source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-stative"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"chapter":{"introduction":["Choose a verb form from its meaning: a state, an activity or a temporary behaviour.","The form tells you how to build the sentence; the context tells you why that form is useful. Read each section with both questions in mind. The examples make one contrast at a time, while the practice mixes the skills so that you learn to recognise the pattern yourself."],"rules":[{"title":"States are not normally continuous","explanation":"Know, believe, own and need commonly describe states rather than activities unfolding moment by moment. They usually take simple forms even when true now. A word such as now does not force every verb into the continuous.","pattern":"I **know** the answer now.","commonMistakes":["I am knowing the answer is not the ordinary standard form for possession of knowledge."],"examples":["Describe present knowledge: “I **know** how to prepare the visitor guide.”","Describe present knowledge: “I **know** how to restore the old portrait.”"],"skill":"form","id":"stative-dynamic-foundation-1","domain":"verbs","referenceIds":["bc-stative"],"readingVersion":"core-2026-09-v3"},{"title":"A verb can change meaning","explanation":"Think can mean hold an opinion or actively consider. Have can mean possess or take part in an activity. Use the meaning in the sentence to decide whether continuous aspect is natural.","pattern":"I **think** it is useful. / I **am thinking about** the problem.","commonMistakes":["A memorised list of stative verbs is not enough: the same spelling can have a dynamic sense."],"examples":["Use present continuous for active consideration: “We **are thinking** about how to prepare the visitor guide.”","Use present continuous for active consideration: “We **are thinking** about how to restore the old portrait.”"],"skill":"meaning","id":"stative-dynamic-foundation-2","domain":"verbs","referenceIds":["bc-stative"],"readingVersion":"core-2026-09-v3"},{"title":"Temporary behaviour with being","explanation":"Be usually describes a state, but **be being + adjective** can describe temporary behaviour. You are being helpful comments on someone’s behaviour now. It does not mean that every adjective works naturally in this pattern.","pattern":"He **is being patient** today.","commonMistakes":["He is being tall does not normally describe temporary behaviour; height is a characteristic."],"examples":["State an opinion, in the simple present: “She **thinks** that preparing the visitor guide is worthwhile.”","State an opinion, in the simple present: “She **thinks** that restoring the old portrait is worthwhile.”"],"skill":"contrast","id":"stative-dynamic-foundation-3","domain":"verbs","referenceIds":["bc-stative"],"readingVersion":"core-2026-09-v3"},{"title":"Perception and deliberate activity","explanation":"See and hear often describe involuntary perception and use simple forms or can. Other senses can describe deliberate activity: tasting soup or smelling a flower. See can also mean meet, which permits a continuous arrangement.","pattern":"I **can hear** music. / She **is tasting** the soup.","commonMistakes":["Advertising and informal emphatic uses sometimes put state verbs in the continuous. Practice here follows the ordinary meaning stated in each prompt."],"examples":["Comment on temporary helpful behaviour: “You **are being** helpful by preparing the visitor guide for us today.”","Comment on temporary helpful behaviour: “You **are being** helpful by restoring the old portrait for us today.”"],"skill":"application","id":"stative-dynamic-foundation-4","domain":"verbs","referenceIds":["bc-stative"],"readingVersion":"core-2026-09-v3"},{"domain":"verbs","id":"lexical-aspect-and-states","title":"States, activities, accomplishments and punctual events","explanation":"Verbs and their complements describe different event types: a state, an ongoing activity, an activity with an endpoint or a brief change. This affects progressive and perfect interpretations. A verb can change its event type with a different sense or object. The categories help explain patterns but do not replace contextual judgement.","pattern":"**run** / **run a kilometre**","examples":["She **was finding** new errors every day.","He **has been building** a house, but he **has built** the wall."],"commonMistakes":["Do not ban every progressive use of a usually stative verb. I’m thinking about it uses a different sense from I think it is correct."],"referenceIds":["cambridge-comprehensive-scope"],"readingVersion":"core-2026-09-v4"}],"recap":["I **know** the answer now.","I **think** it is useful. / I **am thinking about** the problem.","He **is being patient** today.","I **can hear** music. / She **is tasting** the soup."],"readingVersion":"core-2026-09-v4"},"stage":"3 · Time and experience","prerequisites":["present-perfect"],"readingReferenceIds":["bc-stative","cambridge-comprehensive-scope"]}'::jsonb FROM grammar.content_catalog_topics WHERE version='core-2026-09-v3' AND slug='stative-dynamic'
